import { FocusMonitor, FocusOrigin } from '@angular/cdk/a11y';
import { NgIf } from '@angular/common';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostBinding,
  inject,
  Input,
  NgZone,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import {
  QDestroyService,
  QPlatformService,
} from '@questrade/allspark-angular-components/core/services';
import { QTooltipDirective } from '@questrade/allspark-angular-components/tooltip';
import { debounceTime, delay, filter, fromEvent, takeUntil } from 'rxjs';
import { QSliderThumbPosition } from '../types/slider-thumb-position.enum';
import { QSliderThumb } from '../types/slider-thumb.interface';
import { Q_SLIDER, Q_SLIDER_VISUAL_THUMB } from '../types/slider-tokens.const';
import { QSliderVisualThumb } from '../types/slider-visual-thumb-interface';
import { QSlider } from '../types/slider.interface';

@Component({
  selector: 'q-slider-visual-thumb',
  templateUrl: './slider-visual-thumb.component.html',
  styleUrls: ['./slider-visual-thumb.component.scss'],
  imports: [NgIf, QTooltipDirective],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QSliderVisualThumbComponent),
      multi: true,
    },
    { provide: Q_SLIDER_VISUAL_THUMB, useExisting: QSliderVisualThumbComponent },
    QDestroyService,
  ],
})
export class QSliderVisualThumbComponent
  implements QSliderVisualThumb, OnChanges, AfterViewInit, OnDestroy
{
  @Output() readonly focusChange = new EventEmitter<boolean>();
  @Output() readonly keyboardFocusChange = new EventEmitter<boolean>();
  @Output() readonly hoverChange = new EventEmitter<boolean>();

  @Input() tooltip = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input() thumbPosition: QSliderThumbPosition = QSliderThumbPosition.END;
  @Input() valueIndicatorText = '';

  @ViewChild('knob') _knob!: ElementRef<HTMLElement>;
  @ViewChild(QTooltipDirective) _tooltipDirective!: QTooltipDirective;

  @HostBinding('class') hostClass = 'q-slider-thumb';

  _isActive = false;
  _isValueIndicatorVisible = false;
  _hostElement!: HTMLElement;
  private _isFocused = false;
  private _isHovered = false;
  private _sliderInput: QSliderThumb | null = null;
  private _sliderInputEl: HTMLInputElement | null = null;
  private readonly _ngZone = inject(NgZone);
  private readonly _elementRef = inject(ElementRef<HTMLElement>);
  private readonly _slider: QSlider = inject(Q_SLIDER);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _platform = inject(QPlatformService);

  constructor() {
    this._hostElement = this._elementRef.nativeElement;
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.valueIndicatorText) {
      this._onChange();
    }
  }

  ngAfterViewInit(): void {
    this._sliderInput = this._slider._getInput(this.thumbPosition);
    this._sliderInputEl = this._sliderInput?._hostElement ?? null;
    this._attachInputEventListeners();

    if (this._sliderInputEl) {
      this._focusMonitor
        .monitor(this._sliderInputEl)
        .pipe(takeUntil(this._destroy$))
        .subscribe((focusOrigin: FocusOrigin) => {
          this.keyboardFocusChange.emit(focusOrigin === 'keyboard');
        });
    }
  }

  ngOnDestroy(): void {
    if (this._sliderInputEl) this._focusMonitor.stopMonitoring(this._sliderInputEl);
  }

  _getSibling(): QSliderVisualThumb {
    return this._slider._getThumb(
      this.thumbPosition === QSliderThumbPosition.START
        ? QSliderThumbPosition.END
        : QSliderThumbPosition.START,
    );
  }

  _getKnob(): HTMLElement {
    return this._knob.nativeElement;
  }

  _hideTooltip(): void {
    this._dispatchKnobMouseEvent(this.isMobile ? 'touchend' : 'mouseleave');
  }

  _showTooltip(): void {
    if (!this.tooltip) return;

    this._dispatchKnobMouseEvent(this.isMobile ? 'touchstart' : 'mouseenter');
  }

  get isMobile(): boolean {
    return this._platform.IOS || this._platform.ANDROID;
  }

  get isFocused(): boolean {
    return this._isFocused;
  }

  set isFocused(value: boolean) {
    if (this._isFocused !== value) {
      this._isFocused = value;
      this.focusChange.emit(this._isFocused);
    }
  }

  get isHovered(): boolean {
    return this._isHovered;
  }

  set isHovered(value: boolean) {
    this._hostElement.dispatchEvent(new Event('mouseenter'));

    if (this._isHovered !== value) {
      this._isHovered = value;
      this.hoverChange.emit(this._isHovered);
    }
  }

  private _attachInputEventListeners(): void {
    this._ngZone.runOutsideAngular(() => {
      if (this._sliderInputEl) {
        fromEvent(this._sliderInputEl, 'pointermove')
          .pipe(
            filter(() => !this.disabled),
            debounceTime(30),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onPointerMove);

        fromEvent(this._sliderInputEl, 'pointerup')
          .pipe(
            filter(() => !this.disabled),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onDragEnd);

        fromEvent(this._sliderInputEl, 'pointerdown')
          .pipe(
            filter(() => !this.disabled),
            delay(0),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onDragStart);

        fromEvent(this._sliderInputEl, 'pointerleave')
          .pipe(
            filter(() => !this.disabled),
            debounceTime(30),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onMouseLeave);

        fromEvent(this._sliderInputEl, 'focus')
          .pipe(
            filter(() => !this.disabled),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onFocus);

        fromEvent(this._sliderInputEl, 'blur')
          .pipe(
            filter(() => !this.disabled),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onBlur);

        fromEvent(this._sliderInputEl, 'change')
          .pipe(
            filter(() => !this.disabled),
            takeUntil(this._destroy$),
          )
          .subscribe(this._onChange);
      }
    });
  }

  private _onPointerMove = (event: Event): void => {
    const rect = this._hostElement.getBoundingClientRect();
    this.isHovered = this._slider._isCursorOnSliderThumb(event as PointerEvent, rect);
    this.tooltip && this.isHovered ? this._showTooltip() : this._hideTooltip();
  };

  private _onMouseLeave = (): void => {
    this.isHovered = false;
    this._hideTooltip();
  };

  private _onFocus = (): void => {
    this.isFocused = true;
    this.isHovered = false;
    this._showTooltip();
  };

  private _onBlur = (): void => {
    this.isFocused = false;
    this.isHovered = false;
    this._hideTooltip();
  };

  private _onDragStart = (event: Event): void => {
    if ((event as PointerEvent).button !== 0) return;

    this._isActive = true;
    this.keyboardFocusChange.emit(false);
    this._showTooltip();
    this._updateTooltipPosition();
  };

  private _onDragEnd = (): void => {
    this._isActive = false;
  };

  private _onChange = (): void => {
    this._updateTooltipPosition();
  };

  private _dispatchKnobMouseEvent(eventType: string): void {
    this._knob?.nativeElement?.dispatchEvent(new Event(eventType));
  }

  private _updateTooltipPosition(): void {
    if (!this.tooltip) return;

    const tooltipEl = this._tooltipDirective?._getTooltipElement();
    if (tooltipEl) {
      tooltipEl.value = this.valueIndicatorText;
      this._tooltipDirective._overlayRef?.updatePosition();
      tooltipEl._markForCheck();
    }
  }
}
