import { Platform } from '@angular/cdk/platform';
import { NgFor, NgIf } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChild,
  ContentChildren,
  ElementRef,
  HostBinding,
  Input,
  NgZone,
  OnDestroy,
  QueryList,
  ViewChild,
  ViewChildren,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  numberAttribute,
} from '@angular/core';
import { isPresent } from '@questrade/allspark-angular-components/core/utils';
import { Subscription } from 'rxjs';
import { QSliderVisualThumbComponent } from './slider-visual-thumb/slider-visual-thumb.component';
import { QSliderRangeThumb } from './types/slider-range-thumb.interface';
import { QSliderSize } from './types/slider-size.type';
import { QSliderThumbPosition } from './types/slider-thumb-position.enum';
import { QSliderThumb } from './types/slider-thumb.interface';
import { QSliderTickMark } from './types/slider-tick-mark.enum';
import {
  Q_SLIDER,
  Q_SLIDER_RANGE_THUMB,
  Q_SLIDER_THUMB,
  Q_SLIDER_VISUAL_THUMB,
} from './types/slider-tokens.const';
import { QSliderVisualThumb } from './types/slider-visual-thumb-interface';
import { QSlider } from './types/slider.interface';

@Component({
  selector: 'q-slider',
  templateUrl: './slider.component.html',
  styleUrls: ['./slider.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgIf, NgFor, QSliderVisualThumbComponent],
  providers: [{ provide: Q_SLIDER, useExisting: QSliderComponent }],
})
export class QSliderComponent implements AfterViewInit, OnDestroy, QSlider {
  @Input() size: QSliderSize = 'small';
  @Input({ transform: booleanAttribute }) valueLabel = false;
  @Input() displayWith: (value: number) => string = (value: number) => `${value}`;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-slider';

  @Input({ transform: booleanAttribute }) get showTickMarks(): boolean {
    return this._showTickMarks;
  }
  public set showTickMarks(value: boolean) {
    this._showTickMarks = value;
    if (this._showTickMarks) {
      this._updateTickMarkUI();
      this._updateTickMarkTrackUI();
    }
  }

  @Input({ transform: booleanAttribute }) get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: boolean) {
    this._disabled = value;
    const endInput = this._getInput(QSliderThumbPosition.END);
    const startInput = this._getInput(QSliderThumbPosition.START);

    if (endInput) {
      endInput.disabled = this._disabled;
    }
    if (startInput) {
      startInput.disabled = this._disabled;
    }
  }

  @Input({ transform: booleanAttribute }) get tooltip(): boolean {
    return this._tooltip;
  }
  set tooltip(value: boolean) {
    this._tooltip = value;
    this._updateValueIndicatorUIs();
  }

  @Input({ transform: numberAttribute }) get min(): number {
    return this._min;
  }
  set min(value: number) {
    const min = isNaN(value) ? this._min : value;
    if (this._min !== min) {
      this._updateMin(min);
    }
  }

  @Input({ transform: numberAttribute }) get max(): number {
    return this._max;
  }
  set max(value: number) {
    const max = isNaN(value) ? this._max : value;
    if (this._max !== max) {
      this._updateMax(max);
    }
  }

  @Input({ transform: numberAttribute }) get step(): number {
    return this._step;
  }
  set step(value: number) {
    const step = isNaN(value) ? this._step : value;
    if (this._step !== step) {
      this._updateStep(step);
    }
  }

  @Input({ transform: numberAttribute }) get minDistance(): number {
    return this._minDistance;
  }
  set minDistance(value: number) {
    this._minDistance = isNaN(value) ? this._minDistance : value;
  }

  @ContentChildren(Q_SLIDER_RANGE_THUMB, { descendants: false })
  _inputs!: QueryList<QSliderRangeThumb>;

  @ContentChild(Q_SLIDER_THUMB) _input!: QSliderThumb;

  @ViewChildren(Q_SLIDER_VISUAL_THUMB) _thumbs!: QueryList<QSliderVisualThumb>;

  @ViewChild('trackActive') _trackActive!: ElementRef<HTMLElement>;
  @ViewChild('startThumbFocusIndicator') _startThumbFocusIndicator!: ElementRef<HTMLElement>;
  @ViewChild('endThumbFocusIndicator') _endThumbFocusIndicator!: ElementRef<HTMLElement>;
  @ViewChild('startThumb') _startVisualThumb!: QSliderVisualThumbComponent;
  @ViewChild('endThumb') _endVisualThumb!: QSliderVisualThumbComponent;

  @HostBinding('class') get hostClassNames(): string {
    return [
      'q-slider',
      `q-slider-${this.size}`,
      this.disabled && 'q-slider-disabled',
      this.tooltip && 'q-slider-tooltip',
      this._isRange && 'q-slider-range',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _tickMarks: QSliderTickMark[] = [];
  _cachedWidth!: number; // actual width of the slider (offsetWidth, margins are not part of it)
  _cachedLeft!: number;
  _inputPadding!: number;
  _tickMarkTrackWidth = 0;
  _knobRadius = 8;
  _startValueIndicatorText = '';
  _endValueIndicatorText = '';
  _endThumbTransform = '';
  _startThumbTransform = '';
  _isRange = false;
  _hasAnimation = false;
  _startThumbHoverVisible = false;
  _endThumbHoverVisible = false;
  _startThumbFocusVisible = false;
  _endThumbFocusVisible = false;
  _startThumbKeyboardFocusVisible = false;
  _endThumbKeyboardFocusVisible = false;

  private _disabled = false;
  private _tooltip = false;
  private _min = 0;
  private _max = 100;
  private _minDistance = 0;
  private _step = 1;
  private _showTickMarks = false;
  private _dirChangeSubscription: Subscription | null = null;
  private _resizeObserver: ResizeObserver | null = null;
  private _hasViewInitialized = false;
  private _resizeTimer: ReturnType<typeof setTimeout> | null = null;
  private _thumbsOverlap = false;
  private readonly _platform = inject(Platform);
  private readonly _ngZone = inject(NgZone);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _elementRef = inject(ElementRef<HTMLElement>);

  ngAfterViewInit(): void {
    if (this._platform.isBrowser) {
      this._updateDimensions();
    }

    const eInput = this._getInput(QSliderThumbPosition.END);
    const sInput = this._getInput(QSliderThumbPosition.START);
    this._isRange = !!eInput && !!sInput;
    this._cdr.markForCheck();

    this._inputPadding = this._knobRadius;

    this._isRange
      ? this._initUIRange(eInput as QSliderRangeThumb, sInput as QSliderRangeThumb)
      : this._initUINonRange(eInput);

    this._updateTrackUI(eInput);
    this._updateTickMarkUI();
    this._updateTickMarkTrackUI();

    this._observeHostResize();
    this._cdr.markForCheck();
  }

  ngOnDestroy(): void {
    this._dirChangeSubscription?.unsubscribe();
    this._resizeObserver?.disconnect();
    this._resizeObserver = null;
  }

  _updateDimensions(): void {
    this._cachedWidth = this._elementRef.nativeElement.offsetWidth;
    this._cachedLeft = this._elementRef.nativeElement.getBoundingClientRect().left;
  }

  _setTrackActiveStyles(styles: {
    left: string;
    right: string;
    transform: string;
    transformOrigin: string;
  }): void {
    const trackStyle = this._trackActive.nativeElement.style;

    trackStyle.left = styles.left;
    trackStyle.right = styles.right;
    trackStyle.transformOrigin = styles.transformOrigin;
    trackStyle.transform = styles.transform;
  }

  _calcTickMarkTransform(index: number): string {
    const tickLeftOffset = index * (this._tickMarkTrackWidth / (this._tickMarks.length - 1));
    return `translateX(${tickLeftOffset}px)`;
  }

  _onTranslateXChange(source: QSliderThumb): void {
    if (!this._hasViewInitialized) return;

    if (this._isRange) {
      const startInput = this._getInput(QSliderThumbPosition.START) as QSliderRangeThumb;
      const endInput = this._getInput(QSliderThumbPosition.END) as QSliderRangeThumb;
      if (source._thumbPosition === QSliderThumbPosition.START) {
        if (source.value + this._minDistance > endInput.value) {
          source.value = endInput.value - this._minDistance;
          source.translateX =
            endInput.translateX - this._minDistance * (this._cachedWidth / (this._max - this._min));
        }
      } else {
        if (source.value - this._minDistance < startInput.value) {
          source.value = startInput.value + this._minDistance;
          source.translateX =
            startInput.translateX +
            this._minDistance * (this._cachedWidth / (this._max - this._min));
        }
      }
    }

    this._updateThumbUI(source);
    this._updateTrackUI(source);
    this._updateOverlappingThumbUI(source as QSliderRangeThumb);
  }

  _onTranslateXChangeBySideEffect(input1: QSliderRangeThumb, input2: QSliderRangeThumb): void {
    if (!this._hasViewInitialized) return;

    input1._updateThumbUIByValue();
    input2._updateThumbUIByValue();
  }

  _onValueChange(source: QSliderThumb): void {
    if (!this._hasViewInitialized) return;

    this._updateValueIndicatorUI(source);
    this._updateTickMarkUI();
    this._cdr.markForCheck();
  }

  _onMinMaxOrStepChange(): void {
    if (!this._hasViewInitialized) return;

    this._updateTickMarkUI();
    this._updateTickMarkTrackUI();
    this._cdr.markForCheck();
  }

  _onResize(): void {
    if (!this._hasViewInitialized) return;

    this._updateDimensions();
    if (this._isRange) {
      const eInput = this._getInput(QSliderThumbPosition.END) as QSliderRangeThumb;
      const sInput = this._getInput(QSliderThumbPosition.START) as QSliderRangeThumb;

      eInput._updateThumbUIByValue();
      sInput._updateThumbUIByValue();

      eInput._updateStaticStyles();
      sInput._updateStaticStyles();

      eInput._updateMinMax();
      sInput._updateMinMax();

      eInput._updateWidthInactive();
      sInput._updateWidthInactive();
    } else {
      const eInput = this._getInput(QSliderThumbPosition.END);
      if (eInput) {
        eInput._updateThumbUIByValue();
      }
    }

    this._updateTickMarkUI();
    this._updateTickMarkTrackUI();
    this._cdr.detectChanges();
  }

  _updateThumbUI(source: QSliderThumb): void {
    if (this._skipUpdate()) return;

    const thumb = this._getThumb(
      source._thumbPosition === QSliderThumbPosition.END
        ? QSliderThumbPosition.END
        : QSliderThumbPosition.START,
    );

    if (!thumb) {
      throw new Error('Thumb not found for the specified position');
    }

    thumb._hostElement.style.transform = `translateX(${source.translateX}px)`;

    if (this._startThumbFocusIndicator?.nativeElement) {
      this._startThumbFocusIndicator.nativeElement.style.transform = `translateX(${source.translateX}px)`;
    }

    if (this._endThumbFocusIndicator?.nativeElement) {
      this._endThumbFocusIndicator.nativeElement.style.transform = `translateX(${source.translateX}px)`;
    }
  }

  _updateValueIndicatorUI(source: QSliderThumb): void {
    if (this._skipUpdate()) return;

    const valueText = this.displayWith(source.value);

    this._hasViewInitialized
      ? (source._valueText = valueText)
      : source._hostElement?.setAttribute('aria-valuetext', valueText);

    if (this.tooltip) {
      source._thumbPosition === QSliderThumbPosition.START
        ? (this._startValueIndicatorText = valueText)
        : (this._endValueIndicatorText = valueText);

      const visualThumb = this._getThumb(source._thumbPosition);
      valueText.length < 3
        ? visualThumb._hostElement.classList.add('q-slider-thumb-short-value')
        : visualThumb._hostElement.classList.remove('q-slider-thumb-short-value');
    }
  }

  _updateTickMarkUI(): void {
    if (
      !this.showTickMarks ||
      !isPresent(this.step) ||
      !isPresent(this.min) ||
      !isPresent(this.max)
    )
      return;

    const step = this.step > 0 ? this.step : 1;
    this._isRange ? this._updateTickMarkUIRange(step) : this._updateTickMarkUINonRange(step);
  }

  _updateTrackUI(source: QSliderThumb | null): void {
    if (!source || this._skipUpdate()) return;

    this._isRange
      ? this._updateTrackUIRange(source as QSliderRangeThumb)
      : this._updateTrackUINonRange(source as QSliderThumb);
  }

  _getInput(thumbPosition: QSliderThumbPosition): QSliderThumb | QSliderRangeThumb | null {
    if (thumbPosition === QSliderThumbPosition.END && this._input) {
      return this._input;
    }

    if (this._inputs?.length) {
      return thumbPosition === QSliderThumbPosition.START ? this._inputs.first : this._inputs.last;
    }

    return null;
  }

  _getThumb(thumbPosition: QSliderThumbPosition): QSliderVisualThumb {
    return thumbPosition === QSliderThumbPosition.END ? this._thumbs?.last : this._thumbs?.first;
  }

  _setTransition(withAnimation: boolean): void {
    this._hasAnimation = !this._platform.IOS && withAnimation;
    this._elementRef.nativeElement.classList.toggle('q-slider-with-animation', this._hasAnimation);
  }

  _isCursorOnSliderThumb(event: PointerEvent, rect: DOMRect): boolean {
    const radius = rect.width / 2;
    const centerX = rect.x + radius;
    const centerY = rect.y + radius;
    const dx = event.clientX - centerX;
    const dy = event.clientY - centerY;

    return Math.pow(dx, 2) + Math.pow(dy, 2) < Math.pow(radius, 2);
  }

  _thumbFocusChange(focused: boolean, thumb: QSliderVisualThumbComponent): void {
    if (!focused) {
      this._startThumbHoverVisible = false;
      this._endThumbHoverVisible = false;
    }
    this._startThumbFocusVisible = focused && thumb.thumbPosition === QSliderThumbPosition.START;
    this._endThumbFocusVisible = focused && thumb.thumbPosition === QSliderThumbPosition.END;
    this._cdr.detectChanges();
  }

  _thumbKeyboardFocusChange(focused: boolean, thumb: QSliderVisualThumbComponent): void {
    if (!focused) {
      this._startThumbHoverVisible = false;
      this._endThumbHoverVisible = false;
    }
    this._startThumbKeyboardFocusVisible =
      focused && thumb.thumbPosition === QSliderThumbPosition.START;
    this._endThumbKeyboardFocusVisible =
      focused && thumb.thumbPosition === QSliderThumbPosition.END;

    this._cdr.detectChanges();
  }

  _thumbHoverChange(hovered: boolean, thumb: QSliderVisualThumbComponent): void {
    this._startThumbHoverVisible = hovered && thumb.thumbPosition === QSliderThumbPosition.START;
    this._endThumbHoverVisible = hovered && thumb.thumbPosition === QSliderThumbPosition.END;
    this._handleTooltipVisibility(thumb.thumbPosition);
    this._cdr.detectChanges();
  }

  private _handleTooltipVisibility(activeThumbPosition: QSliderThumbPosition): void {
    if (!this._isRange || !this.tooltip) return;

    activeThumbPosition === QSliderThumbPosition.START
      ? this._endVisualThumb._hideTooltip()
      : this._startVisualThumb._hideTooltip();
  }

  private _initUINonRange(eInput: QSliderThumb | null): void {
    if (!eInput) return;

    eInput.initProps();
    eInput.initUI();

    this._updateValueIndicatorUI(eInput);

    this._hasViewInitialized = true;
    eInput._updateThumbUIByValue();
  }

  private _initUIRange(eInput: QSliderRangeThumb, sInput: QSliderRangeThumb): void {
    eInput.initProps();
    eInput.initUI();

    sInput.initProps();
    sInput.initUI();

    eInput._updateMinMax();
    sInput._updateMinMax();

    eInput._updateStaticStyles();
    sInput._updateStaticStyles();

    this._updateValueIndicatorUIs();

    this._hasViewInitialized = true;

    eInput._updateThumbUIByValue();
    sInput._updateThumbUIByValue();
  }

  private _updateMin(min: number): void {
    const prevMin = this._min;
    this._min = min;
    this._isRange ? this._updateMinRange({ old: prevMin, new: min }) : this._updateMinNonRange(min);
    this._onMinMaxOrStepChange();
  }

  private _updateMax(max: number): void {
    const prevMax = this._max;
    this._max = max;
    this._isRange ? this._updateMaxRange({ old: prevMax, new: max }) : this._updateMaxNonRange(max);
    this._onMinMaxOrStepChange();
  }

  private _updateMinRange(min: { old: number; new: number }): void {
    const endInput = this._getInput(QSliderThumbPosition.END) as QSliderRangeThumb;
    const startInput = this._getInput(QSliderThumbPosition.START) as QSliderRangeThumb;

    const oldEndValue = endInput.value;
    const oldStartValue = startInput.value;

    startInput.min = min.new;
    endInput.min = Math.max(min.new, startInput.value);
    startInput.max = Math.min(endInput.max, endInput.value);

    startInput._updateWidthInactive();
    endInput._updateWidthInactive();

    min.new < min.old
      ? this._onTranslateXChangeBySideEffect(endInput, startInput)
      : this._onTranslateXChangeBySideEffect(startInput, endInput);

    if (oldEndValue !== endInput.value) {
      this._onValueChange(endInput);
    }

    if (oldStartValue !== startInput.value) {
      this._onValueChange(startInput);
    }
  }

  private _updateMinNonRange(min: number): void {
    const input = this._getInput(QSliderThumbPosition.END);
    if (input) {
      const oldValue = input.value;

      input.min = min;
      input._updateThumbUIByValue();
      this._updateTrackUI(input);

      if (oldValue !== input.value) {
        this._onValueChange(input);
      }
    }
  }

  private _observeHostResize(): void {
    if (typeof ResizeObserver === 'undefined' || !ResizeObserver) return;

    this._ngZone.runOutsideAngular(() => {
      this._resizeObserver = new ResizeObserver(() => {
        if (this._isActive()) return;

        if (this._resizeTimer) {
          clearTimeout(this._resizeTimer);
        }
        this._onResize();
      });
      this._resizeObserver.observe(this._elementRef.nativeElement);
    });
  }

  private _isActive(): boolean {
    return (
      this._getThumb(QSliderThumbPosition.START)._isActive ||
      this._getThumb(QSliderThumbPosition.END)._isActive
    );
  }

  private _getValue(thumbPosition: QSliderThumbPosition = QSliderThumbPosition.END): number {
    const input = this._getInput(thumbPosition);
    if (!input) return this.min;
    return input.value;
  }

  private _skipUpdate(): boolean {
    return !!(
      this._getInput(QSliderThumbPosition.START)?._skipUIUpdate ||
      this._getInput(QSliderThumbPosition.END)?._skipUIUpdate
    );
  }

  private _areThumbsOverlapping(): boolean {
    const startInput = this._getInput(QSliderThumbPosition.START);
    const endInput = this._getInput(QSliderThumbPosition.END);
    if (!startInput || !endInput) return false;
    return endInput.translateX - startInput.translateX < 20;
  }

  private _updateOverlappingThumbClassNames(source: QSliderRangeThumb): void {
    const sibling = source.getSibling();

    const sourceThumb = this._getThumb(source._thumbPosition);
    sourceThumb._hostElement.classList.toggle('q-slider-thumb-top', this._thumbsOverlap);

    if (sibling) {
      const siblingThumb = this._getThumb(sibling._thumbPosition);
      siblingThumb._hostElement.classList.remove('q-slider-thumb-top');
    }
  }

  private _updateOverlappingThumbUI(source: QSliderRangeThumb): void {
    if (!this._isRange || this._skipUpdate()) return;

    if (this._thumbsOverlap !== this._areThumbsOverlapping()) {
      this._thumbsOverlap = !this._thumbsOverlap;
      this._updateOverlappingThumbClassNames(source);
    }
  }

  private _updateValueIndicatorUIs(): void {
    const eInput = this._getInput(QSliderThumbPosition.END);
    const sInput = this._getInput(QSliderThumbPosition.START);

    if (eInput) {
      this._updateValueIndicatorUI(eInput);
    }
    if (sInput) {
      this._updateValueIndicatorUI(sInput);
    }
  }

  private _updateTickMarkTrackUI(): void {
    if (!this.showTickMarks || this._skipUpdate()) return;

    const step = this._step && this._step > 0 ? this._step : 1;
    const maxValue = Math.floor(this.max / step) * step;
    const percentage = (maxValue - this.min) / (this.max - this.min);
    this._tickMarkTrackWidth = this._cachedWidth * percentage - 10;
    if (this.size === 'medium') {
      this._tickMarkTrackWidth = this._cachedWidth * percentage - 12;
    }
  }

  private _updateTrackUIRange(source: QSliderRangeThumb): void {
    const sibling = source.getSibling();
    if (!sibling || !this._cachedWidth) return;

    const activePercentage = Math.abs(sibling.translateX - source.translateX) / this._cachedWidth;

    if (source._isLeftThumb && this._cachedWidth) {
      this._setTrackActiveStyles({
        left: 'auto',
        right: `${this._cachedWidth - sibling.translateX}px`,
        transformOrigin: 'right',
        transform: `scaleX(${activePercentage})`,
      });
    } else {
      this._setTrackActiveStyles({
        left: `${sibling.translateX}px`,
        right: 'auto',
        transformOrigin: 'left',
        transform: `scaleX(${activePercentage})`,
      });
    }
  }

  private _updateTrackUINonRange(source: QSliderThumb): void {
    this._setTrackActiveStyles({
      left: '0px',
      right: 'auto',
      transformOrigin: 'left',
      transform: `scaleX(${source.fillPercentage})`,
    });
  }

  private _updateTickMarkUINonRange(step: number): void {
    const value = this._getValue();
    const numActive = Math.max(Math.floor((value - this.min) / step), 0);
    let numInactive = Math.max(Math.floor((this.max - value) / step), 0);

    numInactive++;

    this._tickMarks = Array(numActive)
      .fill(QSliderTickMark.ACTIVE)
      .concat(Array(numInactive).fill(QSliderTickMark.INACTIVE));
  }

  private _updateTickMarkUIRange(step: number): void {
    const endValue = this._getValue();
    const startValue = this._getValue(QSliderThumbPosition.START);

    const numInactiveBeforeStartThumb = Math.max(Math.floor((startValue - this.min) / step), 0);
    const numActive = Math.max(Math.floor((endValue - startValue) / step) + 1, 0);
    const numInactiveAfterEndThumb = Math.max(Math.floor((this.max - endValue) / step), 0);
    this._tickMarks = Array(numInactiveBeforeStartThumb)
      .fill(QSliderTickMark.INACTIVE)
      .concat(
        Array(numActive).fill(QSliderTickMark.ACTIVE),
        Array(numInactiveAfterEndThumb).fill(QSliderTickMark.INACTIVE),
      );
  }

  private _updateStep(step: number): void {
    this._step = step;
    this._isRange ? this._updateStepRange() : this._updateStepNonRange();
    this._onMinMaxOrStepChange();
  }

  private _updateStepRange(): void {
    const endInput = this._getInput(QSliderThumbPosition.END) as QSliderRangeThumb;
    const startInput = this._getInput(QSliderThumbPosition.START) as QSliderRangeThumb;

    const oldEndValue = endInput.value;
    const oldStartValue = startInput.value;

    const prevStartValue = startInput.value;

    endInput.min = this._min;
    startInput.max = this._max;

    endInput.step = this._step;
    startInput.step = this._step;

    endInput.min = Math.max(this._min, startInput.value);
    startInput.max = Math.min(this._max, endInput.value);

    startInput._updateWidthInactive();
    endInput._updateWidthInactive();

    endInput.value < prevStartValue
      ? this._onTranslateXChangeBySideEffect(startInput, endInput)
      : this._onTranslateXChangeBySideEffect(endInput, startInput);

    if (oldEndValue !== endInput.value) {
      this._onValueChange(endInput);
    }

    if (oldStartValue !== startInput.value) {
      this._onValueChange(startInput);
    }
  }

  private _updateStepNonRange(): void {
    const input = this._getInput(QSliderThumbPosition.END);
    if (input) {
      const oldValue = input.value;
      input.step = this._step;
      input._updateThumbUIByValue();

      if (oldValue !== input.value) {
        this._onValueChange(input);
      }
    }
  }

  private _updateMaxRange(max: { old: number; new: number }): void {
    const endInput = this._getInput(QSliderThumbPosition.END) as QSliderRangeThumb;
    const startInput = this._getInput(QSliderThumbPosition.START) as QSliderRangeThumb;

    const oldEndValue = endInput.value;
    const oldStartValue = startInput.value;

    endInput.max = max.new;
    startInput.max = Math.min(max.new, endInput.value);
    endInput.min = startInput.value;

    endInput._updateWidthInactive();
    startInput._updateWidthInactive();

    max.new > max.old
      ? this._onTranslateXChangeBySideEffect(startInput, endInput)
      : this._onTranslateXChangeBySideEffect(endInput, startInput);

    if (oldEndValue !== endInput.value) {
      this._onValueChange(endInput);
    }

    if (oldStartValue !== startInput.value) {
      this._onValueChange(startInput);
    }
  }

  private _updateMaxNonRange(max: number): void {
    const input = this._getInput(QSliderThumbPosition.END);
    if (input) {
      const oldValue = input.value;

      input.max = max;
      input._updateThumbUIByValue();
      this._updateTrackUI(input);

      if (oldValue !== input.value) {
        this._onValueChange(input);
      }
    }
  }
}
