import { Directive, forwardRef, inject } from '@angular/core';
import { FormGroupDirective, NG_VALUE_ACCESSOR, NgForm } from '@angular/forms';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { FormFieldControl } from '@questrade/allspark-angular-components/form-control';
import { QSliderThumbDirective } from '../slider-thumb/slider-thumb.directive';
import { QSliderRangeThumb } from '../types/slider-range-thumb.interface';
import { QSliderThumbPosition } from '../types/slider-thumb-position.enum';
import { Q_SLIDER_RANGE_THUMB } from '../types/slider-tokens.const';

@Directive({
  selector: 'input[qSliderStartThumb], input[qSliderEndThumb]',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QSliderRangeThumbDirective),
      multi: true,
    },
    { provide: Q_SLIDER_RANGE_THUMB, useExisting: QSliderRangeThumbDirective },
    { provide: FormFieldControl, useExisting: QSliderRangeThumbDirective },
    QDestroyService,
  ],
})
export class QSliderRangeThumbDirective extends QSliderThumbDirective implements QSliderRangeThumb {
  _isLeftThumb = false;
  _isEndThumb = false;
  private _sibling: QSliderRangeThumbDirective | null = null;

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));

    this._isEndThumb = this._hostElement.hasAttribute('qSliderEndThumb');
    this._isLeftThumb = !this._isEndThumb;
    this._thumbPosition = this._isEndThumb ? QSliderThumbPosition.END : QSliderThumbPosition.START;
  }

  getSibling(): QSliderRangeThumb | null {
    if (!this._sibling) {
      this._sibling = this._slider._getInput(
        this._isEndThumb ? QSliderThumbPosition.START : QSliderThumbPosition.END,
      ) as QSliderRangeThumbDirective | null;
    }
    return this._sibling;
  }

  getMinPos(): number {
    const sibling = this.getSibling();
    if (!this._isLeftThumb && sibling) {
      return sibling.translateX - this._slider.minDistance;
    }
    return this._tickMarkOffset;
  }

  getMaxPos(): number {
    const sibling = this.getSibling();
    if (this._isLeftThumb && sibling) {
      return sibling.translateX + this._slider.minDistance;
    }
    return this._slider._cachedWidth - this._tickMarkOffset;
  }

  _setIsLeftThumb(): void {
    this._isLeftThumb = !this._isEndThumb;
  }

  _updateMinMax(): void {
    const sibling = this.getSibling();

    if (!sibling) return;

    if (this._isEndThumb) {
      this.min = Math.max(this._slider.min, sibling.value + this._slider.minDistance);
      this.max = this._slider.max;
    } else {
      this.min = this._slider.min;
      this.max = Math.min(this._slider.max, sibling.value - this._slider.minDistance);
    }
  }

  _updateStaticStyles(): void {
    this._hostElement.classList.toggle('q-slider-right-input', !this._isLeftThumb);
  }

  override _getDefaultValue(): number {
    return this._isEndThumb && this._slider._isRange ? this.max : this.min;
  }

  override _onInput(): void {
    super._onInput();
    this._updateSibling();
    if (!this._isActive) {
      this._updateWidthInactive();
    }
  }

  override _onNgControlValueChange(): void {
    super._onNgControlValueChange();
    this.getSibling()?._updateMinMax();
  }

  override _onPointerDown(event: PointerEvent): void {
    if (this.disabled || event.button !== 0) return;

    if (this._sibling) {
      this._sibling._updateWidthActive();
      this._sibling._hostElement.classList.add('q-slider-input-no-pointer-events');
    }
    super._onPointerDown(event);
  }

  override _onPointerUp(): void {
    super._onPointerUp();
    setTimeout(() => {
      if (this._sibling) {
        this._sibling._updateWidthInactive();
        this._sibling._hostElement.classList.remove('q-slider-input-no-pointer-events');
      }
    });
  }

  override _onPointerMove(event: PointerEvent): void {
    super._onPointerMove(event);
    if (!this._slider.step && this._isActive) {
      this._updateSibling();
    }
  }

  override _fixValue(event: PointerEvent): void {
    super._fixValue(event);
    this._sibling?._updateMinMax();
  }

  override _clamp(value: number): number {
    return Math.max(Math.min(value, this.getMaxPos()), this.getMinPos());
  }

  override _updateWidthInactive(): void {
    const sibling = this.getSibling();

    if (!sibling) return;

    const maxWidth = this._slider._cachedWidth - this._tickMarkOffset * 2;
    const midValue = this._isEndThumb
      ? this.value - (this.value - sibling.value) / 2
      : this.value + (sibling.value - this.value) / 2;

    const _percentage = this._isEndThumb
      ? (this.max - midValue) / (this._slider.max - this._slider.min)
      : (midValue - this.min) / (this._slider.max - this._slider.min);

    const percentage = this._slider.min < this._slider.max ? _percentage : 1;

    const width = maxWidth * percentage;
    this._hostElement.style.width = `${width}px`;
    this._hostElement.style.padding = '0px';

    if (this._isLeftThumb) {
      this._hostElement.style.left = `-${this._tickMarkOffset}px`;
      this._hostElement.style.right = 'auto';
    } else {
      this._hostElement.style.left = 'auto';
      this._hostElement.style.right = `-${this._tickMarkOffset}px`;
    }
  }

  override writeValue(value: number): void {
    if (this._isControlInitialized || value !== null) {
      this.value = value;
      this._updateWidthInactive();
      this._updateSibling();
    }
  }

  override _setValue(value: string): string {
    super._setValue(value);
    this._updateWidthInactive();
    this._updateSibling();
    return value;
  }

  private _updateSibling(): void {
    const sibling = this.getSibling();

    if (!sibling) return;

    sibling._updateMinMax();
    if (this._isActive) {
      sibling._updateWidthActive();
    } else {
      sibling._updateWidthInactive();
    }
  }
}
