import {
  booleanAttribute,
  ChangeDetectorRef,
  Directive,
  DoCheck,
  ElementRef,
  EventEmitter,
  forwardRef,
  HostBinding,
  HostListener,
  inject,
  Injector,
  Input,
  NgZone,
  numberAttribute,
  OnInit,
  Optional,
  Output,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormControl,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import {
  QDestroyService,
  QPlatformService,
} from '@questrade/allspark-angular-components/core/services';
import { ErrorState, isPresent, voidFn } from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { filter, fromEvent, takeUntil } from 'rxjs';
import { QSliderDragEvent } from '../types/slider-drag-event.interface';
import { QSliderThumbPosition } from '../types/slider-thumb-position.enum';
import { QSliderThumb } from '../types/slider-thumb.interface';
import { Q_SLIDER, Q_SLIDER_THUMB } from '../types/slider-tokens.const';
import { QSlider } from '../types/slider.interface';

@Directive({
  selector: 'input[qSliderThumb]',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QSliderThumbDirective),
      multi: true,
    },
    { provide: Q_SLIDER_THUMB, useExisting: QSliderThumbDirective },
    { provide: FormFieldControl, useExisting: QSliderThumbDirective },
    QDestroyService,
  ],
})
export class QSliderThumbDirective
  extends ErrorState
  implements QSliderThumb, OnInit, DoCheck, ControlValueAccessor, FormFieldControl
{
  @Output() readonly valueChange = new EventEmitter<number>();
  @Output() readonly dragStart = new EventEmitter<QSliderDragEvent>();
  @Output() readonly dragEnd = new EventEmitter<QSliderDragEvent>();

  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();

  @Input({ transform: numberAttribute }) get value(): number {
    return +this._hostElement.value;
  }
  set value(value: number) {
    value = isNaN(value) ? 0 : value;
    const stringValue = value + '';

    if (!this._hasSetInitialValue) {
      this._initialValue = stringValue;
      return;
    }

    if (this._isActive) return;

    this._setValue(stringValue);
  }

  @HostBinding('class') hostClass = 'q-slider-input';
  @HostBinding('attr.type') hostType = 'range';
  @HostBinding('attr.aria-valuetext') get ariaValueText(): string {
    return this._valueText;
  }

  @HostListener('blur') _onBlur(): void {
    this._setIsFocused(false);
    this._onTouchedFn();
  }

  @HostListener('focus') _onFocus(): void {
    this._slider._setTransition(false);
    this._slider._updateTrackUI(this);
    this._setIsFocused(true);
  }

  @HostListener('change') _onChange(): void {
    this.valueChange.emit(this.value);
    if (this._isActive) {
      this._updateThumbUIByValue({ withAnimation: true });
    }
  }

  @HostListener('input') _onInput(): void {
    this._onChangeFn(this.value);
    if (this._slider.step || !this._isActive) {
      this._updateThumbUIByValue({ withAnimation: true });
    }
    this._slider._onValueChange(this);
  }

  controlId = '';
  _thumbPosition: QSliderThumbPosition = QSliderThumbPosition.END;
  _hostElement!: HTMLInputElement;
  _valueText = '';
  _initialValue = '';
  _knobRadius = 8;
  _tickMarkOffset = 4;
  _isActive = false;
  _isFocused = false;
  _skipUIUpdate = false;
  _touched = false;

  protected _onChangeFn: (value: number) => void = voidFn;
  protected _isControlInitialized = false;
  protected readonly _slider: QSlider = inject(Q_SLIDER);
  protected readonly _injector = inject(Injector);

  private _translateX!: number;
  private _hasSetInitialValue = false;
  private _formControl: FormControl | null = null;
  private _onTouchedFn = (): void => {
    this._touched = true;
  };

  private readonly _platform = inject(QPlatformService);
  private readonly _ngZone = inject(NgZone);
  private readonly _elementRef = inject(ElementRef<HTMLInputElement>);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _destroy$ = inject(QDestroyService);

  constructor(
    @Optional() parentFormGroup: FormGroupDirective | null,
    @Optional() parentForm: NgForm | null,
  ) {
    super(parentFormGroup, parentForm);

    this._hostElement = this._elementRef.nativeElement;
    this.controlId = this._hostElement.getAttribute('id') || '';
    this._attachInputEventListeners();
  }

  ngOnInit(): void {
    this._setComponentControl();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  initProps(): void {
    this._updateWidthInactive();
    if (this.disabled !== this._slider.disabled) {
      this._slider.disabled = true;
    }

    this.step = this._slider.step;
    this.min = this._slider.min;
    this.max = this._slider.max;
    this._initValue();
  }

  initUI(): void {
    this._updateThumbUIByValue();
  }

  _initValue(): void {
    this._hasSetInitialValue = true;
    if (!isPresent(this._initialValue)) {
      this.value = this._getDefaultValue();
    } else {
      this._hostElement.value = this._initialValue;
      this._updateThumbUIByValue();
      this._slider._onValueChange(this);
      this._cdr.detectChanges();
    }
  }

  _getDefaultValue(): number {
    return this.min;
  }

  _onNgControlValueChange(): void {
    if (!this._isActive || !this._isFocused) {
      this._slider._onValueChange(this);
      this._updateThumbUIByValue();
    }
    this._slider.disabled = this._formControl?.disabled ?? false;
  }

  _onPointerDown(event: Event): void {
    const pointerEvent = event as PointerEvent;

    if (this.disabled || pointerEvent.button !== 0) return;

    if (this._platform.IOS) {
      const isCursorOnSliderThumb = this._slider._isCursorOnSliderThumb(
        pointerEvent,
        this._slider._getThumb(this._thumbPosition)._hostElement.getBoundingClientRect(),
      );

      this._isActive = isCursorOnSliderThumb;
      this._updateWidthActive();
      this._slider._updateDimensions();
      return;
    }

    this._isActive = true;
    this._setIsFocused(true);
    this._updateWidthActive();
    this._slider._updateDimensions();

    if (!this._slider.step) {
      this._updateThumbUIByPointerEvent(pointerEvent, { withAnimation: true });
    }

    if (!this.disabled) {
      this._handleValueCorrection(pointerEvent);
      this.dragStart.emit({ source: this, parent: this._slider, value: this.value });
    }
  }

  _fixValue(event: PointerEvent): void {
    const xPos = event.clientX - this._slider._cachedLeft;
    const width = this._slider._cachedWidth;
    const step = this._slider.step === 0 ? 1 : this._slider.step;
    const numSteps = Math.floor((this._slider.max - this._slider.min) / step);
    const percentage = xPos / width;
    const fixedPercentage = Math.round(percentage * numSteps) / numSteps;
    const impreciseValue =
      fixedPercentage * (this._slider.max - this._slider.min) + this._slider.min;
    const value = Math.round(impreciseValue / step) * step;
    const prevValue = this.value;

    if (value === prevValue) {
      this._slider._onValueChange(this);
      this._slider.step > 0
        ? this._updateThumbUIByValue()
        : this._updateThumbUIByPointerEvent(event, { withAnimation: this._slider._hasAnimation });
      return;
    }

    this.value = value;
    this.valueChange.emit(this.value);
    this._onChangeFn(this.value);
    this._slider._onValueChange(this);
    this._slider.step > 0
      ? this._updateThumbUIByValue()
      : this._updateThumbUIByPointerEvent(event, { withAnimation: this._slider._hasAnimation });
  }

  _onPointerMove(event: Event): void {
    if (!this._slider.step && this._isActive) {
      this._updateThumbUIByPointerEvent(event as PointerEvent);
    }
  }

  _onPointerUp(): void {
    if (this._isActive) {
      this._isActive = false;
      if (this._platform.SAFARI) {
        this._setIsFocused(false);
      }
      this.dragEnd.emit({ source: this, parent: this._slider, value: this.value });
      setTimeout(() => this._updateWidthInactive(), this._platform.IOS ? 10 : 0);
    }
  }

  _clamp(value: number): number {
    const min = this._tickMarkOffset;
    const max = this._slider._cachedWidth - this._tickMarkOffset;
    return Math.max(Math.min(value, max), min);
  }

  _calcTranslateXByValue(): number {
    return (
      this.percentage * (this._slider._cachedWidth - this._tickMarkOffset * 2) +
      this._tickMarkOffset
    );
  }

  _calcTranslateXByPointerEvent(event: PointerEvent): number {
    return event.clientX - this._slider._cachedLeft;
  }

  _updateWidthActive(): void {
    if (!this._slider._isRange) return;

    const minWidth = this._slider._inputPadding * 2;
    const maxWidth =
      this._slider._cachedWidth + this._slider._inputPadding - minWidth - this._tickMarkOffset * 2;
    const percentage =
      this._slider.min < this._slider.max
        ? (this.max - this.min) / (this._slider.max - this._slider.min)
        : 1;
    const width = maxWidth * percentage + minWidth;
    this._hostElement.style.width = `${width}px`;
    this._hostElement.style.padding = `0 ${this._slider._inputPadding}px`;
  }

  _updateWidthInactive(): void {
    this._hostElement.style.width = `calc(100% + ${
      this._slider._inputPadding * 2 - this._tickMarkOffset * 2
    }px)`;
    this._hostElement.style.left = `-${this._slider._inputPadding - this._tickMarkOffset}px`;
  }

  _updateThumbUIByValue(options?: { withAnimation: boolean }): void {
    this.translateX = this._clamp(this._calcTranslateXByValue());
    this._updateThumbUI(options);
  }

  _updateThumbUIByPointerEvent(event: PointerEvent, options?: { withAnimation: boolean }): void {
    this.translateX = this._clamp(this._calcTranslateXByPointerEvent(event));
    this._updateThumbUI(options);
  }

  _updateThumbUI(options?: { withAnimation: boolean }): void {
    this._slider._setTransition(!!options?.withAnimation);
    this._slider._onTranslateXChange(this);
  }

  // #region ControlValueAccessor implementation

  /** @hidden */
  writeValue(value: number): void {
    if (this._isControlInitialized || value !== null) {
      this.value = value;
    }
  }

  /** @hidden */
  registerOnChange(fn: (value: number) => void): void {
    this._onChangeFn = fn;
    this._isControlInitialized = true;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouchedFn = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  // #endregion

  focus(): void {
    this._hostElement.focus();
  }

  blur(): void {
    this._hostElement.blur();
  }

  get translateX(): number {
    if (this._slider.min >= this._slider.max) {
      this._translateX = this._tickMarkOffset;
      return this._translateX;
    }
    if (!isPresent(this._translateX)) {
      this._translateX = this._calcTranslateXByValue();
    }
    return this._translateX;
  }

  set translateX(value: number) {
    this._translateX = value;
  }

  get min(): number {
    return numberAttribute(this._hostElement.min, 0);
  }

  set min(value: number) {
    this._hostElement.min = value + '';
    this._cdr.markForCheck();
  }

  get max(): number {
    return numberAttribute(this._hostElement.max, 0);
  }

  set max(value: number) {
    this._hostElement.max = value + '';
    this._cdr.markForCheck();
  }

  get step(): number {
    return numberAttribute(this._hostElement.step, 0);
  }

  set step(value: number) {
    this._hostElement.step = value + '';
    this._cdr.markForCheck();
  }

  get disabled(): boolean {
    return booleanAttribute(this._hostElement.disabled);
  }

  set disabled(value: boolean) {
    this._hostElement.disabled = value;
    this._cdr.markForCheck();

    if (this._slider.disabled !== this.disabled) {
      this._slider.disabled = this.disabled;
    }
  }

  /** Calculates the percentage of the current slider value (compared to the max slider value). */
  get percentage(): number {
    if (this._slider.min >= this._slider.max) return 0;
    return (this.value - this._slider.min) / (this._slider.max - this._slider.min);
  }

  /** Calculates the percentage of the active/filled track */
  get fillPercentage(): number {
    if (!this._slider._cachedWidth || this._translateX === 0) return 0;
    return this.translateX / this._slider._cachedWidth;
  }

  protected _setValue(value: string): void {
    this._hostElement.value = value;
    this._updateThumbUIByValue();
    this._slider._onValueChange(this);
    this._cdr.markForCheck();
  }

  private _attachInputEventListeners(): void {
    this._ngZone.runOutsideAngular(() => {
      fromEvent(this._hostElement, 'pointerdown')
        .pipe(
          filter(() => !this.disabled),
          takeUntil(this._destroy$),
        )
        .subscribe(this._onPointerDown.bind(this));

      fromEvent(this._hostElement, 'pointermove')
        .pipe(
          filter(() => !this.disabled),
          takeUntil(this._destroy$),
        )
        .subscribe(this._onPointerMove.bind(this));

      fromEvent(this._hostElement, 'pointerup')
        .pipe(
          filter(() => !this.disabled),
          takeUntil(this._destroy$),
        )
        .subscribe(this._onPointerUp.bind(this));
    });
  }

  private _setIsFocused(value: boolean): void {
    this._isFocused = value;
  }

  private _handleValueCorrection(event: PointerEvent): void {
    this._skipUIUpdate = true;
    setTimeout(() => {
      this._skipUIUpdate = false;
      this._fixValue(event);
    }, 0);
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }
}
